const p = $input.first().json.body;
const fail = () => { throw new Error('Payload inválido: se requiere el contrato de incidente en modo live.'); };
if (!p || typeof p !== 'object' || Array.isArray(p) || p.mode !== 'live' || JSON.stringify(p).length > 24000) fail();
const i=p.incident;
if (!i || typeof i !== 'object' || Array.isArray(i)) fail();
const limits={id:100,title:300,summary:2000,priority:40,status:60,node_id:100};
const incident={};
for(const [key,max] of Object.entries(limits)){if(typeof i[key]!=='string'||i[key].length>max||(key!=='summary'&&!i[key].trim()))fail(); incident[key]=i[key];}
if(!Array.isArray(p.events)||p.events.length>30)fail();
const events=p.events.map(e=>{
 if(!e || typeof e!=='object' || typeof e.event_type!=='string'||!e.event_type.trim()||e.event_type.length>100 || typeof e.confidence!=='number'||!Number.isFinite(e.confidence)||e.confidence<0||e.confidence>1 || typeof e.persistent!=='boolean' || typeof e.detected_at!=='string'||e.detected_at.length>40||!/^\d{4}-\d{2}-\d{2}T/.test(e.detected_at)||!Number.isFinite(Date.parse(e.detected_at)))fail();
 return {event_type:e.event_type,confidence:e.confidence,persistent:e.persistent,detected_at:e.detected_at};
});
return [{json:{incident,events,mode:'live'}}];

const raw=$input.first().json;
if(raw.status !== 'completed') throw new Error('El proveedor no completó el análisis.');
const parts=(raw.output||[]).filter(x=>x.type==='message').flatMap(x=>x.content||[]).filter(x=>x.type==='output_text').map(x=>x.text);
let r; try {r=parts.length===1 && parts[0] && typeof parts[0]==='object' && !Array.isArray(parts[0]) ? parts[0] : JSON.parse(parts.join(''));} catch {throw new Error('El proveedor no devolvió JSON válido.');}
if(!r || typeof r.summary!=='string'||!r.summary.trim()||r.summary.length>4000||typeof r.recommended_action!=='string'||!r.recommended_action.trim()||r.recommended_action.length>1700||!Array.isArray(r.limitations)||r.limitations.length>5||r.limitations.some(x=>typeof x!=='string'||x.length>500)||!Array.isArray(r.sources)||r.sources.length!==0)throw new Error('La respuesta no cumple el contrato.');
const limitations=[...r.limitations,'Solo metadatos proporcionados; no se escuchó audio ni se observaron imágenes.','Confidence es un score del detector, no probabilidad de ilegalidad ni evidencia de identidad.','Sin búsqueda ni verificación externa; fuentes vacías.','Toda decisión requiere revisión humana. No se enviaron notificaciones.'];
const result={summary:r.summary,recommended_action:r.recommended_action+' La decisión final requiere revisión humana.',limitations,sources:[]};
if(typeof raw.model==='string'&&raw.model.length<=100)result.model=raw.model;
return [{json:result}];
